examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
    MonarchConditionEditor(
        value = conditions,
        onValueChange = { conditions = it },
        fields = fields,
        match = match,
        onMatchChange = { match = it },
    )
    MonarchText(text = "A high-priority refund request matches.", style = MonarchTextStyle.Caption)
}

