examples.setup:
val fields = listOf(MonarchConditionField(key = "subject", label = "Subject", type = MonarchConditionFieldType.Text))
var conditions by remember { mutableStateOf(listOf(MonarchCondition.create("c1", fields.first()))) }
var submitted by remember { mutableStateOf(false) }
